fn main() {
    // The texts of the Slint files are translated with the .po files of lang/ (generated by
    // tools/gen_translations.py from the Qt translations); English is the source language.
    let config = slint_build::CompilerConfiguration::new()
        .with_bundled_translations("lang")
        .with_default_translation_context(slint_build::DefaultTranslationContext::None);
    slint_build::compile_with_config("ui/main.slint", config).unwrap();
    println!("cargo:rerun-if-changed=lang");

    // The icon and the version information of the executable.
    #[cfg(windows)]
    {
        let mut res = winresource::WindowsResource::new();
        res.set_icon("assets/app.ico");
        res.set("FileDescription", "Fallout Babylon - translation editor for Fallout 1/2 mods");
        res.set("ProductName", "Fallout Babylon");
        res.set("OriginalFilename", "FalloutBabylon.exe");
        if let Err(e) = res.compile() {
            println!("cargo:warning=cannot embed the icon: {e}");
        }
    }
}
